CREATE OR REPLACE VIEW VW_BORROWER_NET_WORTH AS
SELECT lac.loanApplicationContactId, SUM(las.value) AS TOTAL_ASSETS, SUM(lal.balance) AS TOTAL_LIABILITIES, (SUM(las.value) - SUM(lal.balance)) AS NET_WORTH FROM DW_LOAN.loanapplicationcontact lac JOIN DW_LOAN.loanapplicationcontactasset lca ON lac.loanApplicationContactId = lca.loanApplicationContactId JOIN DW_LOAN.loanapplicationasset las ON lca.loanApplicationAssetId = las.loanApplicationAssetId JOIN DW_LOAN.loanapplicationcontactliability lcl ON lac.loanApplicationContactId = lcl.loanApplicationContactId JOIN DW_LOAN.loanapplicationliability lal ON lcl.loanApplicationLiabilityId = lal.loanApplicationLiabilityId GROUP BY lac.loanApplicationContactId;
